package xyz.jovanstoiljkovic.isa.dtos.song;import xyz.jovanstoiljkovic.isa.dtos.BaseDTO;import xyz.jovanstoiljkovic.isa.dtos.album.AlbumDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.artist.ArtistDTOLeaf;import xyz.jovanstoiljkovic.isa.dtos.like.LikeDTOLeaf;import xyz.jovanstoiljkovic.isa.models.Song;import java.util.List;public class SongDTO extends BaseDTO<Song> {    private Long id;    private String name;    private String url;    private ArtistDTOLeaf artist;    private AlbumDTOLeaf album;    private List<LikeDTOLeaf> likes;    public SongDTO() {    }    public SongDTO(Long id, String name, String url, ArtistDTOLeaf artist, AlbumDTOLeaf album, List<LikeDTOLeaf> likes) {        this.id = id;        this.name = name;        this.url = url;        this.artist = artist;        this.album = album;        this.likes = likes;    }    public Long getId() {        return id;    }    public void setId(Long id) {        this.id = id;    }    public String getName() {        return name;    }    public void setName(String name) {        this.name = name;    }    public String getUrl() {        return url;    }    public void setUrl(String url) {        this.url = url;    }    public ArtistDTOLeaf getArtist() {        return artist;    }    public void setArtist(ArtistDTOLeaf artist) {        this.artist = artist;    }    public AlbumDTOLeaf getAlbum() {        return album;    }    public void setAlbum(AlbumDTOLeaf album) {        this.album = album;    }    public List<LikeDTOLeaf> getLikes() {        return likes;    }    public void setLikes(List<LikeDTOLeaf> likes) {        this.likes = likes;    }}